    await ctx.db.insert("financeSettings",{isInitialized:true,cutoverDate:options.cutoffDate??"2026-07-01",defaultClearingDelayDays:0,updatedAt:1});
    await ctx.db.insert("userProfiles",{userId:`confirmer-${serial}`,tokenIdentifier:`confirmer-${serial}`,name:"مدير COD",role:"admin",branchId,permissions:[],isActive:true});
