    await ctx.db.insert("customerBalances",{key:`${customerId}:${branchId}`,customerId,branchId,receivableBalance:remaining,advanceBalance:0,totalPurchases:100,openingBalancePostedAt:1,updatedAt:1});
    const productId=await ctx.db.insert("products",{name:"منتج COD",sku:`COD-SKU-${serial}`,costPrice:40,sellPrice:50,stock:10,inventoryValue:400,minStock:0,unit:"قطعة",branchId,isActive:true});
