test("COD-13 الشحن بلا حركة مالية",async()=>{const e=await confirmationFixture(13,{paid:20});const deliveryId=await e.t.mutation(api.deliveries.createFromOrderInvoice,e.createArgs);const before=await codState(e);await e.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});const after=await codState(e);assert.equal(after.delivery?.status,"shipped");assert.deepEqual(after.transactions,before.transactions);assert.deepEqual(after.movements,before.movements);assert.deepEqual(after.entries,before.entries);assert.deepEqual(after.balance,before.balance);assert.equal(after.invoice?.paid,20);assert.equal(after.invoice?.remaining,80);assert.equal(after.product?.stock,before.product?.stock);assert.deepEqual(after.inventory,before.inventory);assert.equal(after.order?.status,"ready");});
test("COD-14 تأكيد COD ذري",async()=>{const e=await confirmationFixture(14,{paid:20});const deliveryId=await e.t.mutation(api.deliveries.createFromOrderInvoice,e.createArgs);await e.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});const confirmationId=await e.t.mutation(api.deliveries.confirmDelivered,{deliveryId,codClearingAccountId:e.accountId,date:"2026-07-10",requestId:"confirm-14"});const s=await codState(e),c=s.confirmations[0],tx=s.transactions[0],m=s.movements[0],le=s.entries[0];assert.equal(c?._id,confirmationId);assert.equal(c?.attemptNumber,1);assert.equal(c?.status,"posted");assert.equal(s.delivery?.status,"delivered");assert.equal(s.delivery?.currentConfirmationId,confirmationId);assert.equal(s.order?.status,"delivered");assert.equal(s.invoice?.paid,100);assert.equal(s.invoice?.remaining,0);assert.equal(tx?.type,"delivery_cod_collection");assert.equal(m?.signedAmount,80);assert.equal(m?.accountId,e.accountId);assert.equal(le?.type,"delivery_cod_collection");assert.equal(le?.receivableDelta,-80);assert.equal(s.balance?.receivableBalance,0);assert.equal(s.delivery?.codFinancialTransactionId,tx?._id);assert.equal(s.delivery?.codCustomerLedgerEntryId,le?._id);assert.equal(c?.financialTransactionId,tx?._id);assert.equal(c?.customerLedgerEntryId,le?._id);assert.deepEqual(s.inventory,[]);assert.equal(s.product?.stock,10);});
test("COD-15 تحصيل المتبقي فقط",async()=>{const e=await confirmationFixture(15,{paid:30});const deliveryId=await e.t.mutation(api.deliveries.createFromOrderInvoice,e.createArgs);await e.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});await e.t.mutation(api.deliveries.confirmDelivered,{deliveryId,codClearingAccountId:e.accountId,date:"2026-07-10",requestId:"confirm-15"});const s=await codState(e);assert.equal(s.delivery?.prepaidAmount,30);assert.equal(s.delivery?.codAmount,70);assert.equal(s.account?.currentBalance,70);assert.equal(s.movements.length,1);assert.equal(s.movements[0]?.signedAmount,70);assert.equal(s.entries[0]?.receivableDelta,-70);assert.equal(s.invoice?.paid,100);assert.equal(s.invoice?.remaining,0);assert.equal(s.transactions[0]?.amount,70);assert.equal(s.movements.some(m=>m.signedAmount===30),false);});
test("COD-16 تسليم المدفوع بالكامل",async()=>{const e=await confirmationFixture(16,{paid:100});const deliveryId=await e.t.mutation(api.deliveries.createFromOrderInvoice,e.createArgs);await e.t.mutation(api.deliveries.updateStatus,{id:deliveryId,status:"shipped"});const confirmationId=await e.t.mutation(api.deliveries.confirmDelivered,{deliveryId,date:"2026-07-10",requestId:"confirm-16"});const s=await codState(e);assert.equal(s.confirmations[0]?._id,confirmationId);assert.equal(s.confirmations[0]?.codAmount,0);assert.equal(s.transactions.length,0);assert.equal(s.movements.length,0);assert.equal(s.entries.length,0);assert.equal(s.invoice?.paid,100);assert.equal(s.invoice?.remaining,0);assert.equal(s.invoice?.status,"paid");assert.equal(s.delivery?.status,"delivered");assert.equal(s.order?.status,"delivered");});
