  const codFirst=await e.t.query(api.deliveries.accountPicker,{branchId:e.branchId,purpose:"cod"}),codSecond=await e.t.query(api.deliveries.accountPicker,{branchId:otherBranchId,purpose:"cod"}),destinationFirst=await e.t.query(api.deliveries.accountPicker,{branchId:e.branchId,purpose:"destination"}),destinationSecond=await e.t.query(api.deliveries.accountPicker,{branchId:otherBranchId,purpose:"destination"});assert.deepEqual(codFirst.map(x=>x._id),[e.accountId]);assert.deepEqual(codSecond.map(x=>x._id),[other.accountId]);assert.deepEqual(new Set(destinationFirst.map(x=>x._id)),new Set([ids.cash,ids.bank]));assert.deepEqual(new Set(destinationSecond.map(x=>x._id)),new Set([ids.otherCash,ids.otherBank]));
  const all=[...codFirst,...codSecond,...destinationFirst,...destinationSecond];for(const dto of all){assert.deepEqual(Object.keys(dto).sort(),allowlist);for(const key of forbidden)assert.equal(key in dto,false);}assert.equal(all.some(x=>x._id===ids.disabledCod||x._id===ids.disabledDestination||x._id===ids.forbiddenClearing),false);assert.equal(codFirst.every(x=>x.branchId===e.branchId)&&destinationFirst.every(x=>x.branchId===e.branchId),true);assert.equal(codSecond.every(x=>x.branchId===otherBranchId)&&destinationSecond.every(x=>x.branchId===otherBranchId),true);
