test("COD-34 Pagination وعزل Manager وسياسة Admin",async()=>{
  const e=await confirmationFixture(34,{paid:20}),firstCases=[await addConfirmationCase(e,"34-a",e.branchId),await addConfirmationCase(e,"34-b",e.branchId),await addConfirmationCase(e,"34-c",e.branchId)],secondFirst=await addConfirmationCase(e,"34-x"),otherBranchId=secondFirst.branchId,secondCases=[secondFirst,await addConfirmationCase(e,"34-z",otherBranchId)];
  await e.raw.run(ctx=>ctx.db.insert("userProfiles",{userId:"manager-34",tokenIdentifier:"manager-34",name:"Manager",role:"manager",branchId:e.branchId,permissions:[],isActive:true}));const Manager=e.raw.withIdentity({subject:"manager-34",tokenIdentifier:"manager-34"}),Admin=e.t,firstIds=[] as Id<"deliveries">[],secondIds=[] as Id<"deliveries">[];for(const row of firstCases)firstIds.push(await Admin.mutation(api.deliveries.createFromOrderInvoice,row.createArgs));for(const row of secondCases)secondIds.push(await Admin.mutation(api.deliveries.createFromOrderInvoice,row.createArgs));
  const allowlist=["_id","deliveryNumber","invoiceNumber","orderNumber","customerName","city","status","codAmount","prepaidAmount","shippingCompany","deliveredDate","branchId","accountingVersion","codSettlementId"],hidden=["requestId","idempotencyKey","requestFingerprint","confirmationRequestId","confirmationFingerprint","codFinancialTransactionId","codCustomerLedgerEntryId","currentConfirmationId","createdBy","cancelledBy","reversalRequestId","reversalFingerprint","financialTransactionId","customerLedgerEntryId"];
  async function paginate(actor:typeof Admin,branchId:Id<"branches">){let cursor:string|null=null,isDone=false;const seen:string[]=[],cursors:string[]=[];while(!isDone){const page=await actor.query(api.deliveries.listPaginated,{branchId,paginationOpts:{numItems:1,cursor}});assert.equal(page.page.length<=1,true);if(page.page[0]){assert.equal(seen.includes(String(page.page[0]._id)),false);seen.push(String(page.page[0]._id));const expected=allowlist.filter(key=>key in page.page[0]);assert.deepEqual(Object.keys(page.page[0]).sort(),expected.sort());for(const key of hidden)assert.equal(key in page.page[0],false);}assert.notEqual(page.continueCursor,cursor);cursors.push(page.continueCursor);cursor=page.continueCursor;isDone=page.isDone;}assert.equal(new Set(cursors).size,cursors.length);return seen;}
  const managerIds=await paginate(Manager,e.branchId);assert.deepEqual(new Set(managerIds),new Set(firstIds.map(String)));const managerPinned=await Manager.query(api.deliveries.listPaginated,{branchId:otherBranchId,paginationOpts:{numItems:1,cursor:null}});assert.equal(managerPinned.page.every(x=>x.branchId===e.branchId),true);assert.equal(managerPinned.page.some(x=>secondIds.includes(x._id)),false);
  const adminFirst=await paginate(Admin,e.branchId),adminSecond=await paginate(Admin,otherBranchId);assert.deepEqual(adminFirst,firstIds.map(String).reverse());assert.deepEqual(adminSecond,secondIds.map(String).reverse());assert.equal(new Set([...adminFirst,...adminSecond]).size,5);
});
