  await assert.rejects(Shipping.query(api.deliveries.printDelivery,{deliveryId:otherDelivery}),/فرع/);assert.equal((await Admin.query(api.deliveries.printDelivery,{deliveryId:otherDelivery})).deliveryNumber!==undefined,true);assert.equal((await Accountant.query(api.deliveries.printDelivery,{deliveryId:otherDelivery})).deliveryNumber!==undefined,true);assert.notEqual(otherBranchId,e.branchId);
  const allowlist=["deliveryNumber","orderNumber","invoiceNumber","customerName","customerPhone","city","address","items","totalAmount","prepaidAmount","codAmount","expectedCarrierFee","shippingCompany","trackingNumber","status","deliveredDate","employeeName","reversalReason"],hidden=["_id","branchId","createdBy","requestId","idempotencyKey","requestFingerprint","confirmationRequestId","confirmationFingerprint","codFinancialTransactionId","codCustomerLedgerEntryId","currentConfirmationId","codSettlementId","reversalRequestId","reversalFingerprint"];for(const dto of [by_user,by_token,unknown]){const expected=allowlist.filter(key=>key in dto);assert.deepEqual(Object.keys(dto).sort(),expected.sort());for(const key of hidden)assert.equal(key in dto,false);}
